-- Vida, «calendario de pared» (28-11-2026): toda la página en el fondo «vino»
-- (los bloques seguidos con el mismo fondo forman una sola franja), el año en
-- doce casillas (bloque nuevo «Calendario de pared»), las tres costumbres en
-- tarjetas redondeadas con foto, «También en lo difícil» en una nota crema
-- (llamada en estilo «nota») y, al final, la cita del salmo y dos botones.
--
-- Solo si la página sigue con los bloques de partida de esta instalación (abre
-- con la entradilla de «Un Grupo Parroquial es, antes que nada, gente que se
-- conoce»): si alguien la ha rehecho en el CMS, no se toca.

UPDATE `ContenidoPagina` SET `datos` = JSON_SET(`datos`, '$.bloques', JSON_EXTRACT('[{"tipo":"texto","titulo":"","presentacion":{"fondo":"vino","estilo":"entradilla","ancho":"estrecho"},"html":"<p>Entre un Sábado de Pasión y el siguiente hay un año entero de misas, ensayos, comidas y montajes, y ahí es donde los <strong>hermanos</strong>, unos trescientos cincuenta, se hacen familia.</p>"},{"tipo":"calendarioDePared","titulo":"Un año en el Grupo","presentacion":{"fondo":"vino","alineacionTitulo":"izquierda"},"meses":[{"titulo":"","texto":"Misa de hermandad","foto":"","fotoAlt":"","tono":"normal"},{"titulo":"Cuaresma","texto":"Montaje y ensayos","foto":"/images/cabeceras/hombres-de-trono-1000.webp","fotoAlt":"Hombres de trono bajo los varales","tono":"normal"},{"titulo":"Sábado de Pasión","texto":"La Virgen sale por el barrio","foto":"/images/cabeceras/trono-en-la-calle-1000.webp","fotoAlt":"El trono de la Virgen por las calles del barrio","tono":"destacado"},{"titulo":"","texto":"Semana Santa en Málaga","foto":"","fotoAlt":"","tono":"normal"},{"titulo":"Cruz de mayo","texto":"Convivencia","foto":"","fotoAlt":"","tono":"crema"},{"titulo":"","texto":"Misa de hermandad","foto":"","fotoAlt":"","tono":"normal"},{"titulo":"","texto":"Verano","foto":"","fotoAlt":"","tono":"normal"},{"titulo":"","texto":"Verano","foto":"","fotoAlt":"","tono":"normal"},{"titulo":"","texto":"Vuelta al curso","foto":"","fotoAlt":"","tono":"normal"},{"titulo":"Rosario","texto":"Por el barrio, al caer la tarde","foto":"/images/cabeceras/virgen-de-noche-1000.webp","fotoAlt":"La Virgen de los Desamparados de noche, en el Rosario","tono":"normal"},{"titulo":"Triduo y besamanos","texto":"La fiesta de la Virgen","foto":"/images/cabeceras/virgen-en-su-altar-1000.webp","fotoAlt":"La Virgen en su altar de cultos, entre candeleros","tono":"destacado"},{"titulo":"","texto":"Adviento","foto":"","fotoAlt":"","tono":"normal"}]},{"tipo":"tarjetas","titulo":"","presentacion":{"fondo":"vino","estilo":"redondeadas","columnas":"3"},"tarjetas":[{"titulo":"La misa de hermandad","descripcion":"Una vez al mes, los hermanos se reúnen ante la Virgen para celebrar juntos la eucaristía.","enlace":"","etiqueta":"Cada mes","foto":"/images/cabeceras/virgen-entre-candeleros-1000.webp","fotoAlt":"La Virgen entre candeleros encendidos"},{"titulo":"Montajes y ensayos","descripcion":"Preparar el altar de cultos, montar el trono, ensayar con los hombres de trono: trabajo que une.","enlace":"","etiqueta":"Antes de cada culto","foto":"/images/trono-varales.webp","fotoAlt":"Los varales del trono"},{"titulo":"Convivencias","descripcion":"Comidas, excursiones y la cruz de mayo: ratos para conocerse fuera de la parroquia.","enlace":"","etiqueta":"Varias al año","foto":"/images/nazarenos-1200.webp","fotoAlt":"Nazarenos del Grupo Parroquial"}]},{"tipo":"llamada","titulo":"También en lo difícil","presentacion":{"fondo":"vino","estilo":"nota"},"texto":"El Grupo acompaña a sus hermanos cuando más falta hace: en la enfermedad, en el duelo y en los momentos alegres, como un bautizo o una boda ante la Virgen. Si estás pasando por algo y quieres que lo sepamos, escríbenos.","boton":"Escríbenos","enlace":"/contacto"},{"tipo":"cita","titulo":"","presentacion":{"fondo":"vino","estilo":"clasica","alineacion":"centro"},"texto":"Mirad qué bueno, qué dulce es convivir los hermanos unidos.","autor":"","fuente":"Salmo 133, 1"},{"tipo":"botones","titulo":"","presentacion":{"fondo":"vino","alineacion":"centro"},"botones":[{"texto":"Hazte hermano","enlace":"/hazte-hermano","estilo":"principal"},{"texto":"Ver la agenda","enlace":"/agenda","estilo":"secundario"}]}]', '$'))
